<?php
$monthly=$pdo->query("SELECT DATE_FORMAT(COALESCE(paid_date,due_date),'%Y-%m') mes,SUM(CASE WHEN type='Receita' THEN amount ELSE 0 END) receita,SUM(CASE WHEN type='Despesa' THEN amount ELSE 0 END) despesa FROM finance GROUP BY mes ORDER BY mes DESC LIMIT 12")->fetchAll();
$sources=$pdo->query("SELECT COALESCE(source,'Não informado') source,COUNT(*) qtd FROM leads GROUP BY source ORDER BY qtd DESC")->fetchAll();
$segments=$pdo->query("SELECT COALESCE(segment,'Não informado') segment,COUNT(*) qtd FROM clients GROUP BY segment ORDER BY qtd DESC")->fetchAll();
?>
<div class="page-head"><div><span class="eyebrow">BUSINESS INTELLIGENCE</span><h1>Relatórios</h1><p>Indicadores para apoiar decisões comerciais e operacionais.</p></div><button class="btn" onclick="window.print()">Imprimir relatório</button></div><div class="grid-3"><div class="panel"><h3>Leads por origem</h3><div class="metric-list"><?php foreach($sources as $s):?><div><span><?=e($s['source'])?></span><b><?=$s['qtd']?></b></div><?php endforeach;?></div></div><div class="panel"><h3>Clientes por segmento</h3><div class="metric-list"><?php foreach($segments as $s):?><div><span><?=e($s['segment'])?></span><b><?=$s['qtd']?></b></div><?php endforeach;?></div></div><div class="panel"><h3>Conversão comercial</h3><?php $all=(int)$pdo->query("SELECT COUNT(*) FROM opportunities")->fetchColumn();$wins=(int)$pdo->query("SELECT COUNT(*) FROM opportunities WHERE stage='Ganho'")->fetchColumn();$rate=$all?round($wins/$all*100):0;?><div class="big-number"><?=$rate?>%</div><p class="muted">Oportunidades ganhas / total</p><div class="progress"><i style="width:<?=$rate?>%"></i></div></div></div><div class="panel table-panel"><div class="panel-head"><div><h3>Financeiro mensal</h3><p>Receitas e despesas por competência</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Mês</th><th>Receitas</th><th>Despesas</th><th>Resultado</th></tr></thead><tbody><?php foreach($monthly as $m):?><tr><td><?=e($m['mes'])?></td><td class="positive"><?=money($m['receita'])?></td><td class="negative"><?=money($m['despesa'])?></td><td><b><?=money($m['receita']-$m['despesa'])?></b></td></tr><?php endforeach;?></tbody></table></div></div>
